  "claims": [
    {
      "claim": "Structurally related basic tertiary amines/amides have human absolute oral bioavailability values well above 20%: diphenhydramine 42–72%, dapoxetine 42%, trimipramine 41.4%, and milnacipran 85%.",
      "card_ids": ["C01", "C02", "C03", "C04", "C10", "C13", "C14", "C19", "C27"]
    },
    {
      "claim": "The only below-threshold bioavailability records are species-specific animal values (diphenhydramine low in dogs; ampicillin 12% in fasted calves) and are not transferable affirmative evidence for F < 20% in humans.",
      "card_ids": ["C23", "C24"]
    },
    {
      "claim": "L3 records C30–C41 are oral AUC/Cmax measurements without IV comparators; none measures absolute bioavailability for the query or a close analog, so they do not provide affirmative threshold-relevant F evidence.",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    },
    {
      "claim": "Among L3 records, C33 is the closest scaffold (tertiary amide with basic amine and phenyl groups) and shows measurable oral Cmax in rats, consistent with absorption, but it is a single-dose rat exposure without an IV comparator and cannot quantify F.",
      "card_ids": ["C33"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "L3 records provide oral AUC/Cmax but no IV comparator, so they cannot quantify F.",
    "No experimental data are available on P-gp efflux or first-pass metabolism for the diphenylacetamide/pyrrolidinol scaffold.",
    "The animal low-F records are species-specific and not transferable to human F.",
    "The query's low neutral fraction and high logP leave uncertainty about solubility and dissolution, but this is not affirmative evidence for F < 20%."
  ],
  "decision_summary": "L3 oral exposure records do not provide absolute bioavailability measurements and are mostly for unrelated scaffolds; they do not overturn the prior high prediction based on multiple structurally related compounds with human F > 20%. Prediction remains high with moderate confidence."
}

